const raw = $input.first().json;

// Достаём данные из вложенной структуры
const data = raw.output[0].content[0].text;

// Проверка на ошибку от модели
if (data.error === 'insufficient_content') {
  throw new Error('insufficient_content');
}

// Валидация
if (!data.title || typeof data.title !== 'string') {
  throw new Error('Missing or invalid field: title');
}

if (!['beginner', 'intermediate', 'advanced'].includes(data.difficulty)) {
  throw new Error('Invalid difficulty: ' + data.difficulty);
}

if (!Array.isArray(data.summary_points) || data.summary_points.length < 5 || data.summary_points.length > 7) {
  throw new Error(`summary_points must have 5–7 items, got: ${(data.summary_points || []).length}`);
}

if (!Array.isArray(data.main_concepts) || data.main_concepts.length < 2 || data.main_concepts.length > 5) {
  throw new Error(`main_concepts must have 2–5 items, got: ${(data.main_concepts || []).length}`);
}

return [{ json: data }];

textOptions.schema:
{
  "type": "object",
  "properties": {
    "title": {
      "type": "string",
      "description": "Concise title of the content, max 60 chars"
    },
    "difficulty": {
      "type": "string",
      "enum": ["beginner", "intermediate", "advanced"]
    },
    "summary_points": {
      "type": "array",
      "items": { "type": "string" },
      "description": "5 to 7 key learning points as complete sentences"
    },
    "main_concepts": {
      "type": "array",
      "items": { "type": "string" },
      "description": "2 to 5 short noun phrases describing main concepts"
    },
    "error": {
      "type": ["string", "null"],
      "description": "Set to insufficient_content if content is too sparse, otherwise null"
    }
  },
  "required": ["title", "difficulty", "summary_points", "main_concepts", "error"],
  "additionalProperties": false
}
